/* Prevedi-poi-prova: commetti una previsione PRIMA di rivelare il risultato.
   È qui che si forma la comprensione: sbagliare la previsione rende memorabile
   la sorpresa. Va messo SOPRA l'elemento interattivo del modulo. */
function Predict({ question, options, answer, explain }) {
  const [pick, setPick] = useState(null);
  return (
    <div className="rounded-xl border border-indigo-900 bg-zinc-900 p-4">
      <div className="flex items-center gap-2 mb-2">
        <HelpCircle size={15} className="text-indigo-400" />
        <span className="text-xs uppercase tracking-wide text-indigo-400 font-mono">Prevedi, poi prova</span>
      </div>
      <div className="text-sm text-zinc-200 mb-3 leading-relaxed">{question}</div>
      <div className="grid gap-1.5">
        {options.map((o, i) => {
          const chosen = pick === i, show = pick !== null, right = i === answer;
          const cls = show && right ? "border-emerald-700 bg-emerald-950 text-emerald-200"
            : show && chosen && !right ? "border-red-800 bg-red-950 text-red-200"
            : "border-zinc-800 bg-zinc-950 text-zinc-300 hover:border-zinc-600";
          return <button key={i} disabled={pick !== null} onClick={() => setPick(i)}
            className={`text-left text-sm rounded-lg border px-3 py-2 transition-colors disabled:cursor-default ${cls}`}>{o}</button>;
        })}
      </div>
      {pick !== null && (
        <div className="mt-3 text-xs leading-relaxed text-zinc-300">
          {pick === answer ? <span className="text-emerald-300 font-medium">Esatto. </span> : <span className="text-amber-300 font-medium">Intuizione comune, ma no. </span>}
          {explain} <span className="text-indigo-300">Ora verificalo qui sotto.</span>
        </div>
      )}
    </div>
  );
}

/* Contesto per saltare da un modulo all'altro (usato nel "Quadro completo") */
const NavCtx = React.createContext(() => {});

/* ---------------- Verifica al volo (retrieval practice) ----------------
   Ogni modulo finisce con 1-3 domande. Sbagliare è parte del gioco: si può
   riprovare, e la spiegazione compare appena la risposta è giusta. Quando
   tutte le domande sono corrette, il modulo si segna come "padroneggiato". */

function Quiz({ id, questions = [], onDone }) {
  const [chosen, setChosen] = useState({});
  const solved = questions.map((q, i) => chosen[i] === q.correct);
  const allSolved = questions.length > 0 && solved.every(Boolean);
  useEffect(() => { if (allSolved) onDone && onDone(id); }, [allSolved, id]);
  // riparte da capo quando cambi modulo
  useEffect(() => { setChosen({}); }, [id]);
  if (!questions.length) return null;
  const done = solved.filter(Boolean).length;
  return (
    <div className="mt-7 rounded-xl border border-zinc-800 bg-zinc-900 p-4">
      <div className="flex items-center gap-2 mb-3">
        <ListChecks size={15} className="text-emerald-400" />
        <span className="text-xs uppercase tracking-wide text-emerald-400 font-mono">Verifica al volo</span>
        <span className="ml-auto text-xs font-mono text-zinc-500">{done}/{questions.length}</span>
      </div>
      <p className="text-xs text-zinc-500 mb-4">Prova a rispondere <span className="text-zinc-400">prima</span> di rileggere: è ricordando che si impara, non ripassando. Se sbagli, riprova.</p>
      <div className="space-y-5">
        {questions.map((q, i) => {
          const pick = chosen[i];
          const isSolved = pick === q.correct;
          const wrong = pick !== undefined && pick !== q.correct;
          return (
            <div key={i}>
              <div className="text-sm text-zinc-200 mb-2 leading-relaxed"><span className="text-zinc-500 font-mono mr-1.5">{i + 1}.</span>{q.q}</div>
              <div className="grid gap-1.5">
                {q.options.map((opt, oi) => {
                  const showRight = isSolved && oi === q.correct;
                  const showWrong = wrong && pick === oi;
                  const cls = showRight
                    ? "border-emerald-700 bg-emerald-950 text-emerald-200"
                    : showWrong
                    ? "border-red-800 bg-red-950 text-red-200"
                    : "border-zinc-800 bg-zinc-950 text-zinc-300 hover:border-zinc-600";
                  return (
                    <button key={oi} disabled={isSolved} onClick={() => setChosen((c) => ({ ...c, [i]: oi }))}
                      className={`text-left text-sm rounded-lg border px-3 py-2 transition-colors flex items-center gap-2 disabled:cursor-default ${cls}`}>
                      {showRight ? <CheckCircle2 size={15} className="shrink-0" />
                        : showWrong ? <XCircle size={15} className="shrink-0" />
                        : <Circle size={13} className="shrink-0 text-zinc-600" />}
                      <span>{opt}</span>
                    </button>
                  );
                })}
              </div>
              {isSolved && <div className="mt-2 text-xs leading-relaxed rounded-lg border border-emerald-900 bg-emerald-950 text-emerald-200 px-3 py-2">{q.why}</div>}
              {wrong && <div className="mt-2 text-xs leading-relaxed rounded-lg border border-amber-900 bg-amber-950 text-amber-200 px-3 py-2">Non è quella giusta — riprova. (Suggerimento: ripensa all'esempio che hai appena toccato qui sopra.)</div>}
            </div>
          );
        })}
      </div>
      {allSolved && <div className="mt-4 flex items-center gap-2 text-sm text-emerald-300"><Trophy size={15} /> Fatto: hai padroneggiato questo modulo.</div>}
    </div>
  );
}

/* ---------------- JSON tree ---------------- */

function JsonNode({ value, k, last, depth }) {
  const indent = { paddingLeft: depth * 16 };
  const keyEl = k !== undefined ? <span className="text-indigo-300">"{k}"</span> : null;
  const colon = k !== undefined ? <span className="text-zinc-500">: </span> : null;
  const comma = last ? "" : <span className="text-zinc-600">,</span>;
  if (Array.isArray(value)) {
    return (
      <div style={indent}>
        <div>{keyEl}{colon}<span className="text-zinc-500">[</span></div>
        {value.map((v, i) => <JsonNode key={i} value={v} last={i === value.length - 1} depth={depth + 1} />)}
        <div style={indent}><span className="text-zinc-500">]</span>{comma}</div>
      </div>
    );
  }
  if (value && typeof value === "object") {
    const entries = Object.entries(value);
    return (
      <div style={indent}>
        <div>{keyEl}{colon}<span className="text-zinc-500">{"{"}</span></div>
        {entries.map(([kk, vv], i) => <JsonNode key={kk} k={kk} value={vv} last={i === entries.length - 1} depth={depth + 1} />)}
        <div style={indent}><span className="text-zinc-500">{"}"}</span>{comma}</div>
      </div>
    );
  }
  let valEl;
  if (typeof value === "string") valEl = <span className="text-emerald-300">"{value}"</span>;
  else if (typeof value === "number") valEl = <span className="text-amber-300">{value}</span>;
  else if (typeof value === "boolean") valEl = <span className="text-blue-300">{String(value)}</span>;
  else valEl = <span className="text-blue-300">null</span>;
  return <div style={indent}>{keyEl}{colon}{valEl}{comma}</div>;
}
function JsonTree({ data }) {
  return <div className="font-mono text-[13px] leading-6 overflow-x-auto"><JsonNode value={data} last depth={0} /></div>;
}

