/* Tabella "grande" per il Playground: 64 vendite generate in modo deterministico
   (nessun Math.random → identica a ogni reload). Distribuzione volutamente
   disomogenea per prodotto/categoria, così GROUP BY e HAVING hanno qualcosa da
   dire; la colonna `sconto` è a volte NULL per giocare con IS NULL. */
const SANDBOX_PROD = [
  { prodotto: "Cuffie ANC", categoria: "Audio", base: 79 },
  { prodotto: "Cassa Bluetooth", categoria: "Audio", base: 119 },
  { prodotto: "Tastiera meccanica", categoria: "Accessori", base: 89 },
  { prodotto: "Mouse wireless", categoria: "Accessori", base: 39 },
  { prodotto: 'Monitor 27"', categoria: "Video", base: 229 },
  { prodotto: "Webcam 4K", categoria: "Video", base: 99 },
  { prodotto: "SSD 1TB", categoria: "Storage", base: 109 },
  { prodotto: "Hard Disk 4TB", categoria: "Storage", base: 139 },
];
const SANDBOX_CITTA = ["Berlin", "Milano", "Roma", "Torino", "Napoli"];
function makeVendite() {
  const pat = [0, 4, 0, 1, 4, 5, 0, 2, 4, 6, 1, 4, 0, 7, 3, 5, 4, 0, 6, 1];
  const rows = [];
  for (let i = 0; i < 64; i++) {
    const p = SANDBOX_PROD[pat[i % pat.length]];
    const quantita = (i % 4) + 1;
    rows.push({
      id: i + 1,
      prodotto: p.prodotto,
      categoria: p.categoria,
      citta: SANDBOX_CITTA[(i * 2) % SANDBOX_CITTA.length],
      canale: i % 3 === 0 ? "negozio" : "online",
      mese: (i % 12) + 1,
      quantita,
      importo: p.base * quantita,
      sconto: i % 4 === 0 ? null : ((i % 5) + 1) * 5,
    });
  }
  return rows;
}
const VENDITE = makeVendite();

const TABLES = { users: USERS, orders: ORDERS, vendite: VENDITE };

/* =====================================================================
   MOTORE SQL  (SELECT / WHERE / GROUP BY / aggregati / ORDER BY / LIMIT)
   ===================================================================== */

function coerce(raw) {
  raw = raw.trim();
  if (/^'.*'$/.test(raw)) return { v: raw.slice(1, -1), isStr: true };
  if (/^-?\d+(\.\d+)?$/.test(raw)) return { v: parseFloat(raw), isStr: false };
  return { v: raw, isStr: true };
}
function likeToRegex(pattern) {
  const esc = pattern.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const re = esc.replace(/%/g, ".*").replace(/_/g, ".");
  return new RegExp("^" + re + "$", "i");
}
function parseCondition(str) {
  const t = str.trim();
  const nullM = t.match(/^(\w+)\s+is\s+(not\s+)?null$/i);
  if (nullM) return { col: nullM[1], op: nullM[2] ? "ISNOTNULL" : "ISNULL" };
  const m = t.match(/^(\w+)\s*(>=|<=|!=|<>|=|>|<|LIKE|like)\s*(.+)$/);
  if (!m) throw new Error('Condizione non valida: "' + t + '"');
  let op = m[2].toUpperCase();
  if (op === "<>") op = "!=";
  const { v, isStr } = coerce(m[3]);
  return { col: m[1], op, value: v, isStr };
}
function evalCondition(row, c) {
  if (!(c.col in row)) throw new Error("Colonna sconosciuta: " + c.col);
  const cell = row[c.col];
  if (c.op === "ISNULL") return cell == null;
  if (c.op === "ISNOTNULL") return cell != null;
  if (c.op === "LIKE") return likeToRegex(String(c.value)).test(String(cell));
  let a, b;
  if (typeof cell === "number" && !c.isStr) { a = cell; b = Number(c.value); }
  else { a = String(cell); b = String(c.value); }
  switch (c.op) {
    case "=": return a === b;
    case "!=": return a !== b;
    case ">": return a > b;
    case "<": return a < b;
    case ">=": return a >= b;
    case "<=": return a <= b;
    default: throw new Error("Operatore non supportato: " + c.op);
  }
}
function parseWhere(str) {
  const parts = str.split(/\s+(AND|OR|and|or)\s+/);
  const conds = [parseCondition(parts[0])];
  const ops = [];
  for (let i = 1; i < parts.length; i += 2) { ops.push(parts[i].toUpperCase()); conds.push(parseCondition(parts[i + 1])); }
  return { conds, ops };
}
function evalWhere(row, w) {
  let res = evalCondition(row, w.conds[0]);
  for (let i = 0; i < w.ops.length; i++) {
    const next = evalCondition(row, w.conds[i + 1]);
    res = w.ops[i] === "AND" ? res && next : res || next;
  }
  return res;
}
const AGG_RE = /^(COUNT|SUM|AVG|MIN|MAX)\(\s*(\*|\w+)\s*\)$/i;
function parseSelect(list) {
  return list.split(",").map((s) => s.trim()).map((it) => {
    if (it === "*") return { kind: "all" };
    const m = it.match(AGG_RE);
    if (m) return { kind: "agg", fn: m[1].toUpperCase(), arg: m[2], label: it.replace(/\s+/g, "") };
    if (/^\w+$/.test(it)) return { kind: "col", name: it };
    throw new Error("Elemento SELECT non valido: " + it);
  });
}
function computeAgg(rows, fn, arg) {
  if (fn === "COUNT") return arg === "*" ? rows.length : rows.filter((r) => r[arg] != null).length;
  const nums = rows.map((r) => Number(r[arg])).filter((n) => !isNaN(n));
  if (fn === "SUM") return nums.reduce((a, b) => a + b, 0);
  if (fn === "AVG") return nums.length ? +(nums.reduce((a, b) => a + b, 0) / nums.length).toFixed(2) : 0;
  if (fn === "MIN") return nums.length ? Math.min(...nums) : null;
  if (fn === "MAX") return nums.length ? Math.max(...nums) : null;
}
function parseHaving(str) {
  const m = str.trim().match(/^(.+?)\s*(>=|<=|!=|<>|=|>|<)\s*(.+)$/);
  if (!m) throw new Error('Condizione HAVING non valida: "' + str.trim() + '"');
  let op = m[2]; if (op === "<>") op = "!=";
  return { expr: m[1].replace(/\s+/g, ""), op, value: Number(coerce(m[3]).v) };
}
function evalHaving(row, h) {
  if (!(h.expr in row)) throw new Error("HAVING usa " + h.expr + ", che deve comparire nella SELECT.");
  const a = row[h.expr], b = h.value;
  switch (h.op) {
    case "=": return a === b;
    case "!=": return a !== b;
    case ">": return a > b;
    case "<": return a < b;
    case ">=": return a >= b;
    case "<=": return a <= b;
    default: return false;
  }
}
function runSQL(sql) {
  let s = sql.trim().replace(/;+\s*$/, "");
  if (!/^select/i.test(s)) throw new Error("Per ora il motore esegue solo query SELECT.");
  const fromM = s.match(/\bfrom\s+(\w+)/i);
  if (!fromM) throw new Error("Manca la clausola FROM.");
  const table = TABLES[fromM[1].toLowerCase()];
  if (!table) throw new Error("Tabella sconosciuta: " + fromM[1] + ". Disponibili: users, orders, vendite.");
  const selM = s.match(/^select\s+([\s\S]*?)\s+from\b/i);
  if (!selM) throw new Error("Clausola SELECT non valida.");
  const items = parseSelect(selM[1]);

  const whereM = s.match(/\bwhere\s+([\s\S]*?)(?:\s+group\s+by|\s+order\s+by|\s+limit|$)/i);
  const groupM = s.match(/\bgroup\s+by\s+(\w+)/i);
  const orderM = s.match(/\border\s+by\s+([\s\S]+?)(?:\s+limit\b|$)/i);
  const limitM = s.match(/\blimit\s+(\d+)/i);

  let rows = table.slice();
  if (whereM) { const w = parseWhere(whereM[1].trim()); rows = rows.filter((r) => evalWhere(r, w)); }

  const hasAgg = items.some((i) => i.kind === "agg");
  const groupCol = groupM ? groupM[1] : null;
  let columns = [], outRows = [];

  if (groupCol || hasAgg) {
    if (items.some((i) => i.kind === "all")) throw new Error("Non puoi usare * con GROUP BY o con funzioni di aggregazione.");
    columns = items.map((i) => (i.kind === "col" ? i.name : i.label));
    const groups = {};
    if (groupCol) { for (const r of rows) (groups[r[groupCol]] ??= []).push(r); }
    else groups["__all__"] = rows;
    for (const key of Object.keys(groups)) {
      const grp = groups[key], row = {};
      for (const it of items) {
        if (it.kind === "col") {
          if (it.name !== groupCol) throw new Error("La colonna " + it.name + " deve stare in GROUP BY o dentro una funzione.");
          row[it.name] = grp[0][it.name];
        } else row[it.label] = computeAgg(grp, it.fn, it.arg);
      }
      outRows.push(row);
    }
  } else {
    columns = items.some((i) => i.kind === "all") ? Object.keys(table[0]) : items.map((i) => i.name);
    for (const c of columns) if (!(c in table[0])) throw new Error("Colonna sconosciuta: " + c);
    outRows = rows.map((r) => { const o = {}; for (const c of columns) o[c] = r[c]; return o; });
  }

  const havingM = s.match(/\bhaving\s+([\s\S]*?)(?:\s+order\s+by|\s+limit|$)/i);
  if (havingM) {
    if (!(groupCol || hasAgg)) throw new Error("HAVING richiede GROUP BY o una funzione di aggregazione.");
    const h = parseHaving(havingM[1].trim());
    outRows = outRows.filter((r) => evalHaving(r, h));
  }

  if (orderM) {
    const tok = orderM[1].trim().split(/\s+/);
    const dir = (tok[tok.length - 1] || "ASC").toUpperCase() === "DESC" ? "DESC" : "ASC";
    let col = tok[0];
    if (!columns.includes(col)) { const norm = col.replace(/\s+/g, ""); if (columns.includes(norm)) col = norm; }
    outRows.sort((a, b) => {
      const x = a[col], y = b[col];
      if (x == null || y == null) return 0;
      if (typeof x === "number" && typeof y === "number") return dir === "DESC" ? y - x : x - y;
      return dir === "DESC" ? String(y).localeCompare(String(x)) : String(x).localeCompare(String(y));
    });
  }
  if (limitM) outRows = outRows.slice(0, parseInt(limitM[1], 10));
  return { columns, rows: outRows };
}

function ResultTable({ columns, rows }) {
  return (
    <div className="overflow-x-auto">
      <table className="w-full text-sm font-mono">
        <thead>
          <tr className="text-zinc-500 text-xs border-b border-zinc-800">
            {columns.map((c) => <th key={c} className="text-left py-1.5 pr-4 whitespace-nowrap">{c}</th>)}
          </tr>
        </thead>
        <tbody>
          {rows.map((r, i) => (
            <tr key={i} className="border-b border-zinc-900">
              {columns.map((c) => {
                const v = r[c];
                return (
                  <td key={c} className="py-1.5 pr-4 whitespace-nowrap">
                    {v == null ? <span className="text-zinc-600">NULL</span>
                      : typeof v === "number" ? <span className="text-amber-300">{v}</span>
                      : <span className="text-zinc-200">{String(v)}</span>}
                  </td>
                );
              })}
            </tr>
          ))}
          {rows.length === 0 && <tr><td colSpan={columns.length} className="py-3 text-center text-zinc-600">0 righe</td></tr>}
        </tbody>
      </table>
    </div>
  );
}

