/* Sfida auto-verificata: l'utente compone l'architettura scegliendo i pezzi,
   e l'app gli dice cosa manca (essenziali) e cosa è di troppo (distrattori). */
function DesignChallenge({ brief, pool, reference }) {
  const [sel, setSel] = useState({});
  const [checked, setChecked] = useState(false);
  const essentials = pool.filter((p) => p.role === "essential");
  const gotEss = essentials.filter((p) => sel[p.id]).length;
  const wrongPicked = pool.filter((p) => p.role === "wrong" && sel[p.id]).length;
  const allGood = checked && gotEss === essentials.length && wrongPicked === 0;
  const feedback = pool.filter((p) => p.role === "essential" || sel[p.id]);
  return (
    <div className="mt-7 rounded-xl border border-indigo-900 bg-zinc-900 p-4">
      <div className="flex items-center gap-2 mb-2"><Wrench size={15} className="text-indigo-400" /><span className="text-xs uppercase tracking-wide text-indigo-400 font-mono">Sfida: progettalo tu</span></div>
      <div className="text-sm text-zinc-200 mb-1 leading-relaxed">{brief}</div>
      <p className="text-xs text-zinc-500 mb-3">Prima pensa la tua architettura <span className="text-zinc-400">da zero</span> (schizzala anche su carta). Poi seleziona qui i pezzi che ci metteresti e premi «Verifica»: ti dico cosa manca e cosa è di troppo, con il perché.</p>
      <div className="grid sm:grid-cols-2 gap-1.5 mb-3">
        {pool.map((p) => {
          const on = !!sel[p.id];
          let cls = on ? "border-indigo-600 bg-indigo-950 text-indigo-100" : "border-zinc-800 bg-zinc-950 text-zinc-300 hover:border-zinc-600";
          if (checked) {
            if (p.role === "essential" && on) cls = "border-emerald-700 bg-emerald-950 text-emerald-200";
            else if (p.role === "essential" && !on) cls = "border-red-800 bg-red-950 text-red-200";
            else if (p.role === "wrong" && on) cls = "border-red-800 bg-red-950 text-red-200";
            else if (p.role === "optional" && on) cls = "border-blue-800 bg-blue-950 text-blue-200";
          }
          return (
            <button key={p.id} disabled={checked} onClick={() => { setChecked(false); setSel((s) => ({ ...s, [p.id]: !s[p.id] })); }}
              className={`text-left text-xs rounded-lg border px-3 py-2 transition-colors flex items-center gap-2 disabled:cursor-default ${cls}`}>
              {on ? <CheckSquare size={14} className="shrink-0" /> : <Square size={14} className="shrink-0 text-zinc-600" />}
              <span>{p.label}</span>
            </button>
          );
        })}
      </div>
      {!checked && <button onClick={() => setChecked(true)} className="px-4 py-2 rounded-md bg-indigo-600 hover:bg-indigo-500 text-white text-sm font-medium transition-colors">Verifica</button>}
      {checked && (
        <div className="space-y-2">
          <div className={`text-sm font-medium ${allGood ? "text-emerald-300" : "text-amber-300"}`}>{allGood ? "Architettura solida: tutti gli elementi essenziali, nessuno di troppo." : `Essenziali presi: ${gotEss}/${essentials.length}${wrongPicked ? ` · ${wrongPicked} da evitare` : ""}. Rivedi i punti qui sotto.`}</div>
          <div className="space-y-1.5">
            {feedback.map((p) => (
              <div key={p.id} className="text-xs leading-relaxed text-zinc-400">
                <span className={`font-mono mr-1 ${p.role === "essential" ? (sel[p.id] ? "text-emerald-300" : "text-red-300") : p.role === "wrong" ? "text-red-300" : "text-blue-300"}`}>
                  {p.role === "essential" ? (sel[p.id] ? "✓ giusto" : "✗ mancava") : p.role === "wrong" ? "✗ da evitare" : "≈ opzionale"}
                </span>
                <span className="text-zinc-200">{p.label}</span> — {p.why}
              </div>
            ))}
          </div>
          {reference && <div className="text-xs text-zinc-400 leading-relaxed rounded-lg border border-zinc-800 bg-zinc-950 p-3"><span className="text-indigo-300 font-mono">Soluzione di riferimento — </span>{reference}</div>}
          <button onClick={() => { setChecked(false); setSel({}); }} className="text-xs text-zinc-500 hover:text-zinc-300 flex items-center gap-1"><RotateCcw size={12} /> riprova da capo</button>
        </div>
      )}
    </div>
  );
}

function fmtNum(n) {
  if (n >= 1e9) return (n / 1e9).toFixed(1) + " Mld";
  if (n >= 1e6) return (n / 1e6).toFixed(1) + " Mln";
  if (n >= 1e3) return (n / 1e3).toFixed(1) + "k";
  return String(Math.round(n));
}
function fmtBytes(b) {
  const u = ["B", "KB", "MB", "GB", "TB", "PB"];
  let i = 0; while (b >= 1024 && i < u.length - 1) { b /= 1024; i++; }
  return b.toFixed(b < 10 && i > 0 ? 1 : 0) + " " + u[i];
}

/* =====================================================================
   SYSTEM DESIGN — diagramma d'architettura animato (stile ByteByteGo /
   metodo Hello Interview: si costruisce un pezzo alla volta, ognuno con
   la scelta e il trade-off; poi puoi ricostruirlo tu e ti commento le scelte)
   ===================================================================== */

const ARCH_TONE = {
  zinc: { b: "#4a495e", i: "#9c9bb2" }, indigo: { b: "#6b4be4", i: "#b7a6fb" },
  emerald: { b: "#059669", i: "#6ee7b7" }, amber: { b: "#b45309", i: "#fbbf24" },
  blue: { b: "#2563eb", i: "#93c5fd" }, red: { b: "#dc2626", i: "#fca5a5" },
};
// Il canvas archify (dentro l'iframe) è ormai spogliato del suo chrome
// (toolbar/titolo/barra path-map-lens/footer — vedi diagrams-src/embed.mjs),
// quindi la sua altezza reale varia (Guidami apre una barra capitoli, ecc.).
// Niente più scroll interno: misuriamo l'altezza vera del documento
// incorporato e la applichiamo all'iframe, così la pagina scorre come un
// contenuto unico invece di intrappolare uno scroll dentro una card fissa.
function useArchifyAutoHeight(iframeRef) {
  const [height, setHeight] = useState(420);
  const roRef = useRef(null);
  useEffect(() => () => roRef.current?.disconnect(), []);
  function attach() {
    const doc = iframeRef.current?.contentWindow?.document;
    if (!doc) return;
    const measure = () => setHeight(Math.max(220, doc.documentElement.scrollHeight));
    measure();
    roRef.current?.disconnect();
    roRef.current = new ResizeObserver(measure);
    roRef.current.observe(doc.documentElement);
  }
  return [height, attach];
}

function Architecture({ arch }) {
  const slug = ARCH_SLUG.get(arch);
  const base = slug ? `diagrams/${slug}.html` : null;
  const [mode, setMode] = useState("guide"); // guide | build | explore — le tre modalità pilotano TUTTE lo stesso iframe archify
  const [step, setStep] = useState(1);
  const [placed, setPlaced] = useState([]);
  const [log, setLog] = useState([]);
  const [auto, setAuto] = useState(false);
  const [ready, setReady] = useState(false);
  const [nonce, setNonce] = useState(0); // forza il remount (reload pulito) ad ogni cambio tab
  const timer = useRef(null);
  const iframeRef = useRef(null);
  const [frameH, attachAutoHeight] = useArchifyAutoHeight(iframeRef);
  const byId = useMemo(() => { const m = {}; arch.nodes.forEach((n) => (m[n.id] = n)); return m; }, [arch]);

  // Guidami: naviga il canvas archify vero via il suo #view=/#beat= documentato
  // (il testo pieno resta qui in React, l'highlight/camera li fa il motore archify).
  function pushHash(stepNum) {
    const win = iframeRef.current?.contentWindow;
    const id = arch.steps[stepNum - 1]?.id;
    if (win && id) win.location.hash = `#view=guidami&beat=${id}`;
  }
  function goStep(next) {
    const clamped = Math.max(1, Math.min(arch.steps.length, next));
    setStep(clamped);
    if (mode === "guide" && ready) pushHash(clamped);
  }
  function switchMode(m) {
    if (m === mode) return;
    setAuto(false);
    setMode(m);
    setReady(false);
    if (m === "build") { setPlaced([]); setLog([]); }
    setNonce((n) => n + 1); // reload pulito: azzera hash/story residui o overlay di build
  }
  function handleLoad() {
    setReady(true);
    attachAutoHeight();
    const win = iframeRef.current?.contentWindow;
    if (!win) return;
    if (mode === "guide") pushHash(step);
    else if (mode === "build") { win.__lessonBuild?.start(); placed.forEach((id) => win.__lessonBuild?.place(id)); }
  }

  useEffect(() => {
    if (!auto || mode !== "guide") { clearInterval(timer.current); return; }
    timer.current = setInterval(() => {
      setStep((s) => {
        if (s >= arch.steps.length) { setAuto(false); return s; }
        const ns = s + 1;
        if (ready) pushHash(ns);
        return ns;
      });
    }, 2200);
    return () => clearInterval(timer.current);
  }, [auto, mode, arch, ready]);
  useEffect(() => () => clearInterval(timer.current), []);

  const rec = arch.steps.find((s) => !placed.includes(s.id));
  const palette = useMemo(() => [
    ...arch.nodes.map((n) => ({ id: n.id, label: n.label, icon: n.icon, kind: "node" })),
    ...(arch.distractors || []).map((d) => ({ ...d, kind: "distractor" })),
  ].sort((a, b) => a.label.localeCompare(b.label)), [arch]);

  // Ricostruiscilo tu: stessa palette/log di sempre, ma i pezzi piazzati vengono
  // rivelati DENTRO il canvas archify vero via window.__lessonBuild (override
  // iniettato in ogni case-*.html — vedi diagrams-src/buildmode.mjs).
  function pick(item) {
    if (item.kind === "distractor") { setLog((l) => [{ t: "bad", m: `✗ ${item.label} — ${item.why}` }, ...l].slice(0, 6)); return; }
    if (placed.includes(item.id)) { setLog((l) => [{ t: "warn", m: `${item.label}: è già nell'architettura.` }, ...l].slice(0, 6)); return; }
    const recBefore = rec, stepObj = arch.steps.find((s) => s.id === item.id), isRec = recBefore && recBefore.id === item.id;
    const last = placed.length + 1 === arch.nodes.length;
    setPlaced((p) => [...p, item.id]);
    if (ready) iframeRef.current?.contentWindow?.__lessonBuild?.place(item.id);
    setLog((l) => {
      const entry = isRec
        ? { t: "good", m: `✓ ${item.label} — ${stepObj.choice}` }
        : { t: "warn", m: `≈ ${item.label}: scelta lecita. Io però avrei aggiunto prima «${byId[recBefore.id].label}» — ${recBefore.choice}` };
      const end = last ? [{ t: "done", m: "🎉 Architettura ricostruita! Passa a «Guidami» per i trade-off che ti sei perso." }] : [];
      return [...end, entry, ...l].slice(0, 6);
    });
  }
  function restartBuild() {
    setPlaced([]); setLog([]);
    if (ready) iframeRef.current?.contentWindow?.__lessonBuild?.start();
  }

  const cur = step > 0 ? arch.steps[step - 1] : null;
  const curNode = cur ? byId[cur.id] : null;
  const activeEdges = arch.edges.filter((e) => e.from === cur?.id || e.to === cur?.id);
  const logColor = { good: "text-emerald-300", warn: "text-amber-300", bad: "text-red-300", done: "text-indigo-300" };
  const src = !base ? undefined : mode === "guide" ? `${base}#view=guidami&beat=${arch.steps[step - 1]?.id || arch.steps[0].id}` : base;

  return (
    <Card>
      <div className="flex items-center gap-2 mb-3 flex-wrap">
        <Network size={15} className="text-indigo-400" />
        <span className="text-sm font-semibold text-zinc-200">Architettura — {arch.title}</span>
        <div className="ml-auto flex flex-wrap gap-1.5">
          <Btn tone="ghost" active={mode === "guide"} onClick={() => switchMode("guide")}>Guidami</Btn>
          <Btn tone="ghost" active={mode === "build"} onClick={() => switchMode("build")}>Ricostruiscilo tu</Btn>
          <Btn tone="ghost" active={mode === "explore"} onClick={() => switchMode("explore")}>Esplora</Btn>
        </div>
      </div>

      {base ? (
        <div className="rounded-lg border border-zinc-800 bg-zinc-950 overflow-hidden">
          <iframe key={nonce} ref={iframeRef} src={src} onLoad={handleLoad} title={`archify · ${arch.title}`}
            className="w-full block" style={{ height: frameH, border: 0 }} />
        </div>
      ) : (
        <Note tone="amber" icon={AlertTriangle}>Diagramma archify non disponibile per questo caso.</Note>
      )}

      {mode === "guide" && (
        <div className="mt-3">
          <div className="flex items-center gap-2 mb-2">
            <Btn tone="ghost" onClick={() => { setAuto(false); goStep(step - 1); }} disabled={step <= 1}>◀</Btn>
            <Btn tone="ghost" onClick={() => { setAuto(false); goStep(step + 1); }} disabled={step >= arch.steps.length}>Avanti ▶</Btn>
            <button onClick={() => { if (step >= arch.steps.length) goStep(1); setAuto((a) => !a); }} className="px-3 py-2 rounded-md bg-indigo-600 hover:bg-indigo-500 text-white text-sm font-medium transition-colors flex items-center gap-1.5"><Play size={13} />{auto ? "pausa" : "auto"}</button>
            <span className="ml-auto font-mono text-xs text-zinc-600">passo {step} / {arch.steps.length}</span>
          </div>
          <div className="flex items-center gap-1 mb-3">
            {arch.steps.map((s, i) => (
              <button key={s.id} onClick={() => { setAuto(false); goStep(i + 1); }} title={byId[s.id].label}
                className={`h-1.5 rounded-full transition-all ${i < step ? "bg-indigo-500" : "bg-zinc-700 hover:bg-zinc-600"} ${i === step - 1 ? "w-7" : "w-3"}`} />
            ))}
          </div>
          {curNode && (
            <Card tone={curNode.tone === "zinc" ? "indigo" : curNode.tone}>
              <div className="flex items-center gap-2 mb-1.5"><curNode.icon size={18} style={{ color: (ARCH_TONE[curNode.tone] || ARCH_TONE.zinc).i }} /><span className="font-semibold text-white">{curNode.label}</span>{curNode.sub && <Pill tone="zinc">{curNode.sub}</Pill>}</div>
              <p className="text-sm text-zinc-300 leading-relaxed mb-1.5">{cur.choice}</p>
              {cur.trade && <div className="text-xs text-zinc-400 leading-relaxed"><span className="text-amber-300 font-mono">trade-off</span> — {cur.trade}</div>}
              {activeEdges.length > 0 && (
                <div className="mt-2.5 pt-2.5 border-t border-zinc-800">
                  <div className="text-[10px] uppercase tracking-wide text-zinc-500 font-mono mb-1.5">Come si collega</div>
                  <div className="space-y-1">
                    {activeEdges.map((e, i) => (
                      <div key={i} className="flex items-center gap-1.5 font-mono text-[11px] flex-wrap">
                        <span className="text-indigo-300">{byId[e.from].label}</span>
                        <ArrowRight size={11} className="text-zinc-600" />
                        <span className="text-indigo-300">{byId[e.to].label}</span>
                        {e.label && <span className="text-amber-300">· {e.label}</span>}
                        {e.dashed && <span className="text-zinc-500">(async)</span>}
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </Card>
          )}
        </div>
      )}

      {mode === "build" && (
        <div className="mt-3">
          <p className="text-xs text-zinc-500 mb-2">Ricostruiscila da zero: clicca i pezzi nell'ordine in cui li aggiungeresti. Ti dico se sono giusti, se l'ordine ha senso, e cosa avresti dovuto mettere. Attenzione: nella lista ci sono anche <span className="text-red-300">distrattori</span>.</p>
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-1.5 mb-3">
            {palette.map((p) => {
              const done = p.kind === "node" && placed.includes(p.id), PIcon = p.icon;
              return (
                <button key={p.id} onClick={() => pick(p)} disabled={done}
                  className={`text-left text-xs rounded-lg border px-2.5 py-2 transition-colors flex items-center gap-1.5 ${done ? "border-emerald-800 bg-emerald-950 text-emerald-300" : "border-zinc-800 bg-zinc-950 text-zinc-300 hover:border-zinc-600"}`}>
                  {done ? <CheckCircle2 size={13} className="shrink-0" /> : <PIcon size={13} className="shrink-0 text-zinc-500" />}<span className="truncate">{p.label}</span>
                </button>
              );
            })}
          </div>
          <div className="flex items-center gap-2 mb-2">
            <span className="text-xs text-zinc-500">{placed.length}/{arch.nodes.length} pezzi</span>
            {rec && <button onClick={() => setLog((l) => [{ t: "warn", m: `💡 Prossimo consigliato: «${byId[rec.id].label}».` }, ...l].slice(0, 6))} className="text-xs text-indigo-400 hover:text-indigo-300">suggerisci il prossimo</button>}
            <button onClick={restartBuild} className="text-xs text-zinc-500 hover:text-zinc-300 flex items-center gap-1 ml-auto"><RotateCcw size={12} /> ricomincia</button>
          </div>
          {log.length > 0 && (
            <div className="rounded-lg border border-zinc-800 bg-zinc-950 p-3 space-y-1.5">
              {log.map((e, i) => <div key={i} className={`text-xs leading-relaxed ${logColor[e.t]}`}>{e.m}</div>)}
            </div>
          )}
        </div>
      )}

      {mode === "explore" && (
        <p className="mt-3 text-xs text-zinc-500">Vista archify completa — pan/zoom, lente semantica, ricerca, focus ed export. Quello che vedi è il diagramma vero, non una copia.</p>
      )}
    </Card>
  );
}

/* =====================================================================
   SYSTEM DESIGN — diagramma di sequenza (il flusso nel tempo, stile
   Hello Interview: le interazioni compaiono un passo alla volta, ognuna
   con la spiegazione del collegamento richiesta→risposta)
   ===================================================================== */
// Mappa index-dello-step -> id del messaggio archify (`m0`, `m1`, ...). Rispecchia
// esattamente la logica di piegatura dei self-call in diagrams-src/build.mjs
// (un self-call senza messaggio proprio eredita l'id del messaggio precedente,
// o del successivo se non ce n'è ancora uno).
function seqRelationIds(seq) {
  const ids = new Array(seq.steps.length).fill(null);
  let mCount = 0;
  const pending = [];
  seq.steps.forEach((s, i) => {
    if (s.from === s.to) {
      if (mCount > 0) ids[i] = `m${mCount - 1}`;
      else pending.push(i);
      return;
    }
    const rid = `m${mCount}`; mCount++;
    ids[i] = rid;
    while (pending.length) ids[pending.shift()] = rid;
  });
  return ids;
}

function Sequence({ seq }) {
  const slug = SEQ_SLUG.get(seq);
  const base = slug ? `diagrams/${slug}.html` : null;
  const [mode, setMode] = useState("guide"); // guide | explore — entrambe pilotano lo stesso iframe archify
  const [step, setStep] = useState(1);
  const [auto, setAuto] = useState(false);
  const [ready, setReady] = useState(false);
  const [nonce, setNonce] = useState(0);
  const timer = useRef(null);
  const iframeRef = useRef(null);
  const [frameH, attachAutoHeight] = useArchifyAutoHeight(iframeRef);
  const idx = useMemo(() => { const m = {}; seq.actors.forEach((a, i) => (m[a.id] = i)); return m; }, [seq]);
  const relIds = useMemo(() => seqRelationIds(seq), [seq]);
  const n = seq.steps.length;

  // Guidami: pilota il canvas archify vero via il suo #relation=<id> documentato
  // (Direct Relationship Pin) — apre il Semantic Passport e pinna esattamente
  // quella freccia, senza bisogno di nascondere/rivelare nulla a mano.
  function pushHash(stepNum) {
    const win = iframeRef.current?.contentWindow;
    const rid = relIds[stepNum - 1];
    if (win && rid) win.location.hash = `#relation=${rid}`;
  }
  function goStep(next) {
    const clamped = Math.max(1, Math.min(n, next));
    setStep(clamped);
    if (mode === "guide" && ready) pushHash(clamped);
  }
  function switchMode(m) {
    if (m === mode) return;
    setAuto(false); setMode(m); setReady(false);
    setNonce((x) => x + 1);
  }
  function handleLoad() {
    setReady(true);
    attachAutoHeight();
    if (mode === "guide") pushHash(step);
  }

  useEffect(() => {
    if (!auto || mode !== "guide") { clearInterval(timer.current); return; }
    timer.current = setInterval(() => {
      setStep((s) => {
        if (s >= n) { setAuto(false); return s; }
        const ns = s + 1;
        if (ready) pushHash(ns);
        return ns;
      });
    }, 1900);
    return () => clearInterval(timer.current);
  }, [auto, mode, seq, ready]);
  useEffect(() => () => clearInterval(timer.current), []);

  const cur = seq.steps[step - 1];
  const fromA = cur ? seq.actors[idx[cur.from]] : null;
  const toA = cur ? seq.actors[idx[cur.to]] : null;
  const firstRel = relIds[step - 1];
  const src = !base ? undefined : mode === "guide" && firstRel ? `${base}#relation=${firstRel}` : base;

  return (
    <Card>
      <div className="flex items-center gap-2 mb-1 flex-wrap">
        <ArrowLeftRight size={15} className="text-emerald-400" />
        <span className="text-sm font-semibold text-zinc-200">Sequenza — {seq.title}</span>
        <div className="ml-auto flex flex-wrap gap-1.5">
          <Btn tone="ghost" active={mode === "guide"} onClick={() => switchMode("guide")}>Guidami</Btn>
          <Btn tone="ghost" active={mode === "explore"} onClick={() => switchMode("explore")}>Esplora</Btn>
        </div>
      </div>
      <p className="text-xs text-zinc-500 mb-3">Chi parla con chi, in che ordine. Ogni freccia è un messaggio; il tempo scorre verso il basso.</p>

      {base ? (
        <div className="rounded-lg border border-zinc-800 bg-zinc-950 overflow-hidden">
          <iframe key={nonce} ref={iframeRef} src={src} onLoad={handleLoad} title={`archify · ${seq.title}`}
            className="w-full block" style={{ height: frameH, border: 0 }} />
        </div>
      ) : (
        <Note tone="amber" icon={AlertTriangle}>Diagramma archify non disponibile per questo caso.</Note>
      )}

      {mode === "guide" && (
        <div className="mt-3">
          <div className="flex items-center gap-2 mb-2">
            <Btn tone="ghost" onClick={() => { setAuto(false); goStep(step - 1); }} disabled={step <= 1}>◀</Btn>
            <Btn tone="ghost" onClick={() => { setAuto(false); goStep(step + 1); }} disabled={step >= n}>Avanti ▶</Btn>
            <button onClick={() => { if (step >= n) goStep(1); setAuto((a) => !a); }} className="px-3 py-2 rounded-md bg-emerald-600 hover:bg-emerald-500 text-white text-sm font-medium transition-colors flex items-center gap-1.5"><Play size={13} />{auto ? "pausa" : "auto"}</button>
            <span className="ml-auto font-mono text-xs text-zinc-600">passo {step} / {n}</span>
          </div>
          <div className="flex items-center gap-1 mb-3">
            {seq.steps.map((s, i) => (
              <button key={i} onClick={() => { setAuto(false); goStep(i + 1); }}
                className={`h-1.5 rounded-full transition-all ${i < step ? "bg-emerald-500" : "bg-zinc-700 hover:bg-zinc-600"} ${i === step - 1 ? "w-7" : "w-3"}`} />
            ))}
          </div>
          {cur && (
            <Card tone="emerald">
              <div className="flex items-center gap-2 mb-1.5 flex-wrap font-mono text-[12px]">
                <Pill tone={fromA.tone}>{fromA.label}</Pill>
                <ArrowRight size={13} className="text-zinc-600" />
                <Pill tone={toA.tone}>{toA.label}</Pill>
                <span className="text-emerald-300">{cur.label}</span>
              </div>
              {cur.note && <p className="text-sm text-zinc-300 leading-relaxed">{cur.note}</p>}
            </Card>
          )}
        </div>
      )}

      {mode === "explore" && (
        <p className="mt-3 text-xs text-zinc-500">Vista archify completa — pan/zoom, lente semantica, ricerca, focus ed export. Quello che vedi è il diagramma vero, non una copia.</p>
      )}
    </Card>
  );
}

